+
+@Injectable()
+export class MasterDataService {
+  constructor(private readonly prisma: PrismaService) {}
+
+  async createTenant(dto: CreateTenantDto) {
+    return this.prisma.tenant.create({
+      data: {
+        code: dto.code.trim(),
+        name: dto.name.trim(),
+        status: dto.status ?? TenantStatus.ACTIVE,
+      },
+    });
+  }
+
+  async listTenants(actor: RequestUser) {
+    return this.prisma.tenant.findMany({
+      where: { id: actor.tenantId },
+      orderBy: { createdAt: "desc" },
+    });
+  }
+
+  async getTenant(tenantId: string, actor: RequestUser) {
+    this.assertTenantAccess(tenantId, actor);
+    const tenant = await this.prisma.tenant.findUnique({ where: { id: tenantId } });
+    if (!tenant) throw new NotFoundException("Tenant not found.");
+    return tenant;
+  }
+
+  async createUser(dto: CreateUserDto, actor: RequestUser) {
+    this.assertTenantAccess(dto.tenantId, actor);
+    await this.ensureTenant(dto.tenantId);
+    return this.prisma.user.create({
+      data: {
+        id: dto.id,
+        tenantId: dto.tenantId,
+        username: dto.username.trim(),
+        email: dto.email.trim().toLowerCase(),
+        displayName: dto.displayName.trim(),
+        role: dto.role,
+        status: dto.status ?? UserStatus.ACTIVE,
+      },
+    });
+  }
+
+  async listUsersByTenant(tenantId: string, actor: RequestUser) {
+    this.assertTenantAccess(tenantId, actor);
+    return this.prisma.user.findMany({
+      where: { tenantId },
+      orderBy: [{ createdAt: "desc" }, { username: "asc" }],
+    });
+  }
+
+  async getUser(tenantId: string, userId: string, actor: RequestUser) {
+    this.assertTenantAccess(tenantId, actor);
+    const user = await this.prisma.user.findFirst({
+      where: { id: userId, tenantId },
+    });
+    if (!user) throw new NotFoundException("User not found.");
+    return user;
+  }
+
+  async updateUserStatus(tenantId: string, userId: string, status: UserStatus, actor: RequestUser) {
+    this.assertTenantAccess(tenantId, actor);
+    await this.getUser(tenantId, userId, actor);
+    return this.prisma.user.update({
+      where: { id: userId },
+      data: { status },
+    });
+  }
+
+  async resolveDisplayNames(tenantId: string, ids: string[]) {
+    if (!ids.length) return {};
+    const uniqueIds = [...new Set(ids.filter(Boolean))];
+    const users = await this.prisma.user.findMany({
+      where: { tenantId, id: { in: uniqueIds } },
+      select: { id: true, displayName: true },
+    });
+    return Object.fromEntries(users.map((u) => [u.id, u.displayName]));
+  }
+
+  async ensureUsersForLegacyIds(tenantId: string, legacyIds: string[]) {
+    if (!legacyIds.length) return;
+    await this.ensureTenant(tenantId);
+    const uniqueIds = [...new Set(legacyIds.filter(Boolean))];
+    const existing = await this.prisma.user.findMany({
+      where: { tenantId, id: { in: uniqueIds } },
+      select: { id: true },
+    });
+    const existingSet = new Set(existing.map((u) => u.id));
+    const missing = uniqueIds.filter((id) => !existingSet.has(id));
+
+    for (const id of missing) {
+      const safe = id.toLowerCase().replace(/[^a-z0-9._-]/g, "-");
+      await this.prisma.user.create({
+        data: {
+          id,
+          tenantId,
+          username: safe.slice(0, 40) || `user-${Date.now()}`,
+          email: `${safe || "legacy.user"}@legacy.local`,
+          displayName: id,
+          role: "PROJECT_MANAGER",
+          status: UserStatus.ACTIVE,
+        },
+      });
+    }
+  }
+
+  private assertTenantAccess(tenantId: string, actor: RequestUser) {
+    if (tenantId !== actor.tenantId) {
+      throw new ForbiddenException("Cross-tenant access denied.");
+    }
+  }
+
+  private async ensureTenant(tenantId: string) {
+    const tenant = await this.prisma.tenant.findUnique({ where: { id: tenantId } });
+    if (!tenant) throw new BadRequestException("Tenant does not exist.");
+    return tenant;
+  }
+}
