+import { useCallback, useEffect, useMemo, useState } from "react";
+import { apiClient } from "../api/client";
+import { endpoints } from "../api/endpoints";
+import type { MasterUserRecord } from "../types";
+
+export const useUserDirectory = (tenantId?: string) => {
+  const [users, setUsers] = useState<MasterUserRecord[]>([]);
+
+  const load = useCallback(async () => {
+    if (!tenantId) return;
+    try {
+      const { data } = await apiClient.get<MasterUserRecord[]>(endpoints.usersByTenant(tenantId));
+      setUsers(data ?? []);
+    } catch {
+      setUsers([]);
+    }
+  }, [tenantId]);
+
+  useEffect(() => {
+    load();
+  }, [load]);
+
+  const byId = useMemo(() => Object.fromEntries(users.map((u) => [u.id, u.displayName])), [users]);
+  const resolve = useCallback((id?: string | null) => (id ? byId[id] ?? id : "-"), [byId]);
+
+  return { users, byId, resolve };
+};
